CREATE TABLE IF NOT EXISTS "metrics_5m" AS
SELECT date_bin(INTERVAL '5 minutes', f."bucket", TIMESTAMPTZ '2000-01-01 00:00:00+00') AS "bucket",
       f."name" AS "name",
       f."type" AS "type",
       f."dimensions_key" AS "dimensions_key",
       sum(f."value_count")::bigint AS "value_count",
       (array_agg(f."value_last" ORDER BY (f."value_last" IS NULL), f."bucket" DESC))[1] AS "value_last",
       max(f."value_max") AS "value_max",
       min(f."value_min") AS "value_min",
       sum(f."value_sum")::double precision AS "value_sum"
FROM "metrics_1m" AS f
GROUP BY 1, 2, 3, 4
WITH NO DATA;
