CREATE OR REPLACE TRIGGER "sqlflow_rollup_metrics_total_15m_ins"
  AFTER INSERT ON "metrics_total_5m"
  REFERENCING NEW TABLE AS changed
  FOR EACH STATEMENT EXECUTE FUNCTION "sqlflow_rollup_metrics_total_15m"();
CREATE OR REPLACE TRIGGER "sqlflow_rollup_metrics_total_15m_upd"
  AFTER UPDATE ON "metrics_total_5m"
  REFERENCING NEW TABLE AS changed
  FOR EACH STATEMENT EXECUTE FUNCTION "sqlflow_rollup_metrics_total_15m"();

CREATE OR REPLACE FUNCTION "sqlflow_rollup_metrics_total_1h"() RETURNS trigger
LANGUAGE plpgsql AS $fn$
BEGIN
  -- The lock serializes writers only because each statement in READ COMMITTED
  -- takes a new snapshot, which sees the writer the lock waited on.
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'sqlflow rollup metrics_total_1h needs READ COMMITTED, not %', current_setting('transaction_isolation');
  END IF;
  IF current_setting('sqlflow.rollup_backfill', true) IS DISTINCT FROM 'on' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('sqlflow_rollup:metrics', 0));
    PERFORM pg_advisory_xact_lock(hashtextextended('metrics_total_1h:' || extract(epoch FROM touched.b)::bigint, 0))
    FROM (SELECT DISTINCT date_bin(INTERVAL '1 hours', "bucket", TIMESTAMPTZ '2000-01-01 00:00:00+00') AS b FROM changed ORDER BY 1) AS touched;
  END IF;

  INSERT INTO "metrics_total_1h" ("bucket", "name", "type", "value_count", "value_max", "value_min", "value_sum")
  SELECT date_bin(INTERVAL '1 hours', f."bucket", TIMESTAMPTZ '2000-01-01 00:00:00+00'), f."name", f."type", sum(f."value_count")::bigint, max(f."value_max"), min(f."value_min"), sum(f."value_sum")::double precision
  FROM "metrics_total_15m" AS f
  JOIN (SELECT DISTINCT date_bin(INTERVAL '1 hours', "bucket", TIMESTAMPTZ '2000-01-01 00:00:00+00') AS b FROM changed) AS touched
    ON f."bucket" >= touched.b AND f."bucket" < touched.b + INTERVAL '1 hours'
  GROUP BY 1, 2, 3
  ON CONFLICT ("bucket", "name", "type") DO UPDATE SET "value_count" = excluded."value_count", "value_max" = excluded."value_max", "value_min" = excluded."value_min", "value_sum" = excluded."value_sum";
  RETURN NULL;
END $fn$;
CREATE OR REPLACE TRIGGER "sqlflow_rollup_metrics_total_1h_ins"
  AFTER INSERT ON "metrics_total_15m"
  REFERENCING NEW TABLE AS changed
  FOR EACH STATEMENT EXECUTE FUNCTION "sqlflow_rollup_metrics_total_1h"();
CREATE OR REPLACE TRIGGER "sqlflow_rollup_metrics_total_1h_upd"
  AFTER UPDATE ON "metrics_total_15m"
  REFERENCING NEW TABLE AS changed
  FOR EACH STATEMENT EXECUTE FUNCTION "sqlflow_rollup_metrics_total_1h"();

