-- Backfill the grains built from the source. Their inserts fire the triggers,
-- which fill every coarser grain once.
SET LOCAL sqlflow.rollup_backfill = on;
INSERT INTO "metrics_5m" ("bucket", "name", "type", "dimensions_key", "value_count", "value_last", "value_max", "value_min", "value_sum")
SELECT date_bin(INTERVAL '5 minutes', f."bucket", TIMESTAMPTZ '2000-01-01 00:00:00+00'), f."name", f."type", f."dimensions_key", sum(f."value_count")::bigint, (array_agg(f."value_last" ORDER BY (f."value_last" IS NULL), f."bucket" DESC))[1], max(f."value_max"), min(f."value_min"), sum(f."value_sum")::double precision
FROM "metrics_1m" AS f
GROUP BY 1, 2, 3, 4
ON CONFLICT ("bucket", "name", "type", "dimensions_key") DO UPDATE SET "value_count" = excluded."value_count", "value_last" = excluded."value_last", "value_max" = excluded."value_max", "value_min" = excluded."value_min", "value_sum" = excluded."value_sum";
INSERT INTO "metrics_total_5m" ("bucket", "name", "type", "value_count", "value_max", "value_min", "value_sum")
SELECT date_bin(INTERVAL '5 minutes', f."bucket", TIMESTAMPTZ '2000-01-01 00:00:00+00'), f."name", f."type", sum(f."value_count")::bigint, max(f."value_max"), min(f."value_min"), sum(f."value_sum")::double precision
FROM "metrics_1m" AS f
GROUP BY 1, 2, 3
ON CONFLICT ("bucket", "name", "type") DO UPDATE SET "value_count" = excluded."value_count", "value_max" = excluded."value_max", "value_min" = excluded."value_min", "value_sum" = excluded."value_sum";
SET LOCAL sqlflow.rollup_backfill = off;
